from typing import List

from app.ai.agents.base_agent import BaseAgent
from app.ai.orchestrator.state import LexIntelState
from app.ai.logging.logger import AILogger

logger = AILogger("agent.legal_drafting")

_DISCLAIMER_HEADER = (
    "⚠️ AI GENERATED DRAFT — REQUIRES LAWYER REVIEW\n"
    "This document was automatically generated by LexIntel AI. "
    "It is NOT a substitute for professional legal advice. "
    "All [PLACEHOLDER] fields must be completed by a qualified lawyer. "
    "Do not file this document without legal verification.\n"
    + "=" * 60 + "\n\n"
)

# Document types to auto-generate based on case context
_DRAFT_TYPES = [
    "Legal Notice",
    "Consumer Complaint",
    "Written Statement",
]


class LegalDraftingAgent(BaseAgent):
    """
    Phase 3B — Agent 3: Legal Drafting

    Consumes completed Phase 3A + prediction + strategy state to
    automatically generate professionally formatted legal document drafts.
    Each draft includes an AI disclaimer and [PLACEHOLDER] markers.
    Never overwrites prior state fields.
    """

    agent_name = "legal_drafting"
    prompt_name = "legal_drafting"

    async def execute(self, state: LexIntelState) -> LexIntelState:
        doc_intel = state.get("document_intelligence") or {}
        legal_research = state.get("legal_research") or {}
        evidence_analysis = state.get("evidence_analysis") or {}
        strategy = state.get("legal_strategy") or {}

        _sanitized = state.get("sanitized_input") or ""
        case_summary = doc_intel.get("summary") or _sanitized
        parties = ", ".join(doc_intel.get("parties") or [])
        organizations = ", ".join(doc_intel.get("organizations") or [])
        dates = ", ".join((doc_intel.get("dates") or [])[:5])
        applicable_acts = ", ".join(legal_research.get("applicable_acts") or [])
        legal_sections = ", ".join(doc_intel.get("legal_sections") or [])
        remedies = "; ".join((legal_research.get("remedies") or [])[:5])
        evidence_summary = evidence_analysis.get("analysis_summary") or ""

        # Determine which document types to draft from strategy suggestions
        doc_types = self._select_doc_types(strategy)

        prompt = self.get_prompt()
        drafts: List[dict] = []

        for doc_type in doc_types:
            try:
                response = await self.invoke_llm(
                    prompt.system,
                    prompt.render_user(
                        document_type=doc_type,
                        case_summary=case_summary[:800],
                        parties=parties[:300],
                        organizations=organizations[:200],
                        dates=dates[:200],
                        applicable_acts=applicable_acts[:400],
                        legal_sections=legal_sections[:300],
                        remedies=remedies[:400],
                        evidence_summary=evidence_summary[:400],
                    ),
                )
                parsed = self.parse_json_response(response.content)
                # Inject disclaimer into content
                if "content" in parsed:
                    parsed["content"] = _DISCLAIMER_HEADER + parsed["content"]
                parsed["ai_generated"] = True
                parsed["requires_lawyer_review"] = True
                drafts.append(parsed)
            except Exception as exc:
                logger.warning("Draft generation failed", doc_type=doc_type, error=str(exc))
                drafts.append({
                    "document_type": doc_type,
                    "title": f"{doc_type} (Draft Failed)",
                    "content": _DISCLAIMER_HEADER + f"Draft generation failed: {exc}",
                    "ai_generated": True,
                    "requires_lawyer_review": True,
                    "error": str(exc),
                })

        state["legal_drafts"] = drafts
        logger.info("Legal drafting complete", drafts=len(drafts))
        return state

    def _select_doc_types(self, strategy: dict) -> List[str]:
        """Pick document types based on strategy suggestions, fallback to defaults."""
        suggested = []
        for s in (strategy.get("strategies") or [])[:3]:
            for action in (s.get("recommended_actions") or []):
                action_lower = action.lower()
                if "notice" in action_lower and "Legal Notice" not in suggested:
                    suggested.append("Legal Notice")
                elif "complaint" in action_lower and "Consumer Complaint" not in suggested:
                    suggested.append("Consumer Complaint")
                elif "affidavit" in action_lower and "Affidavit" not in suggested:
                    suggested.append("Affidavit")
                elif "rti" in action_lower and "RTI Application" not in suggested:
                    suggested.append("RTI Application")
        # Always include at least the defaults
        for dt in _DRAFT_TYPES:
            if dt not in suggested:
                suggested.append(dt)
        return suggested[:3]  # cap at 3 to control LLM cost
